import java.util.random.RandomGenerator;

public final class Strategy {
  public static String chooseMove(int turn, String myHistory, String opponentHistory, RandomGenerator rng) {
    if (turn != myHistory.length() || myHistory.length() != opponentHistory.length()) return "X";
    if (!(myHistory + opponentHistory).matches("[RPS]*")) return "X";
    return new String[] {"R", "P", "S"}[turn % 3];
  }
}

